//! Keystroke overlay renderer (Pro): keycap badges for recorded modifier
//! combos, rasterized into the generated overlay plate and composited topmost
//! on the final raster.
//!
//! The display model mirrors `packages/editor-core/src/keystrokes/*` — the
//! committed `src/testdata/keystroke-layouts.json` fixture is generated by the
//! TypeScript side and asserted here field-by-field, so the editor preview
//! (which injects the same generated SVG into the DOM) and this rasterizer
//! produce identical artwork. Source timestamps map through the render
//! segments, so trims, splits, and speed changes keep badges aligned.

use std::collections::BTreeMap;
use std::sync::{Arc, OnceLock};

use serde::Deserialize;
use tiny_skia::{Pixmap, PixmapPaint, Transform};

use crate::capture::keystrokes::{ordered_modifiers, KeystrokeEvent, KeystrokeModifier};
use crate::exports::cursor::source_time_for_output;
use crate::exports::{KeystrokeOverlay, RenderSegment};

const ENTER_MS: f64 = 160.0;
const EXIT_MS: f64 = 220.0;
const EVICT_MS: f64 = 180.0;
const REPEAT_MERGE_MS: u64 = 900;
const CAP_HEIGHT_RATIO: f64 = 0.038;

const JETBRAINS_MONO: &[u8] =
    include_bytes!("../../../../../packages/overlay-engine/fonts/jetbrainsmono.ttf");

fn keystroke_fontdb() -> Arc<resvg::usvg::fontdb::Database> {
    static DB: OnceLock<Arc<resvg::usvg::fontdb::Database>> = OnceLock::new();
    DB.get_or_init(|| {
        // Deterministic badge font — never falls back to system fonts, so an
        // export renders identically on any machine.
        let mut db = resvg::usvg::fontdb::Database::new();
        db.load_font_data(JETBRAINS_MONO.to_vec());
        db.set_monospace_family("JetBrains Mono");
        Arc::new(db)
    })
    .clone()
}

// ---------------------------------------------------------------------------
// Metrics + theme (mirror keystroke-geometry.ts)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy)]
pub(crate) struct Metrics {
    cap_height: f64,
    cap_pad_x: f64,
    cap_gap: f64,
    row_gap: f64,
    pill_pad_x: f64,
    pill_pad_y: f64,
    cap_radius: f64,
    pill_radius: f64,
    font_px: f64,
    glyph_box: f64,
    margin: f64,
    shadow_blur: f64,
    shadow_offset_y: f64,
    char_advance: f64,
}

fn keystroke_metrics(canvas_height: f64, scale: f64) -> Metrics {
    let cap_height = (canvas_height * CAP_HEIGHT_RATIO * scale).round().max(18.0);
    let font_px = (cap_height * 0.46).round();
    Metrics {
        cap_height,
        cap_pad_x: (cap_height * 0.34).round(),
        cap_gap: (cap_height * 0.14).round().max(2.0),
        row_gap: (cap_height * 0.3).round().max(6.0),
        pill_pad_x: (cap_height * 0.32).round(),
        pill_pad_y: (cap_height * 0.24).round(),
        cap_radius: (cap_height * 0.26).round(),
        pill_radius: (cap_height * 0.4).round(),
        font_px,
        glyph_box: (cap_height * 0.52).round(),
        margin: (canvas_height * 0.055).round(),
        shadow_blur: (cap_height * 0.3).round(),
        shadow_offset_y: (cap_height * 0.08).round(),
        char_advance: font_px * 0.6,
    }
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct Theme {
    pill_fill: &'static str,
    pill_opacity: f64,
    pill_stroke: &'static str,
    pill_stroke_opacity: f64,
    cap_fill_top: &'static str,
    cap_fill_top_opacity: f64,
    cap_fill_bottom: &'static str,
    cap_fill_bottom_opacity: f64,
    cap_stroke: &'static str,
    cap_stroke_opacity: f64,
    cap_highlight: &'static str,
    cap_highlight_opacity: f64,
    text: &'static str,
    text_opacity: f64,
    count_text: &'static str,
    count_text_opacity: f64,
    shadow_color: &'static str,
    shadow_opacity: f64,
}

