// ---------------------------------------------------------------------------
// Glyph table (shared JSON with the preview) + tokenize (mirror keystroke-model.ts)
// ---------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct GlyphTable {
    #[serde(rename = "strokeWidth")]
    stroke_width: f64,
    #[serde(rename = "strokeLinecap")]
    stroke_linecap: String,
    #[serde(rename = "strokeLinejoin")]
    stroke_linejoin: String,
    glyphs: BTreeMap<String, GlyphDef>,
}

#[derive(Debug, Deserialize)]
struct GlyphDef {
    fill: String,
    paths: Vec<String>,
}

fn glyph_table() -> &'static GlyphTable {
    static TABLE: OnceLock<GlyphTable> = OnceLock::new();
    TABLE.get_or_init(|| {
        serde_json::from_str(include_str!(
            "../../../../../packages/editor-core/src/keystrokes/key-glyphs.json"
        ))
        .expect("key-glyphs.json must parse")
    })
}

#[derive(Debug, Clone, PartialEq)]
struct Cap {
    glyph_id: Option<String>,
    text: Option<String>,
    is_modifier: bool,
}

fn modifier_glyph(modifier: KeystrokeModifier, platform: &str) -> &'static str {
    match (modifier, platform) {
        (KeystrokeModifier::Ctrl, _) => "mod-ctrl",
        (KeystrokeModifier::Alt, _) => "mod-alt",
        (KeystrokeModifier::Shift, _) => "mod-shift",
        (KeystrokeModifier::Meta, "macos") => "mod-meta-cmd",
        (KeystrokeModifier::Meta, "windows") => "mod-meta-win",
        (KeystrokeModifier::Meta, _) => "mod-meta-super",
    }
}

fn modifier_text(modifier: KeystrokeModifier, platform: &str) -> &'static str {
    match (modifier, platform) {
        (KeystrokeModifier::Ctrl, _) => "Ctrl",
        (KeystrokeModifier::Alt, "macos") => "Opt",
        (KeystrokeModifier::Alt, _) => "Alt",
        (KeystrokeModifier::Shift, _) => "Shift",
        (KeystrokeModifier::Meta, "windows") => "Win",
        (KeystrokeModifier::Meta, "macos") => "Cmd",
        (KeystrokeModifier::Meta, "linux") => "Super",
        (KeystrokeModifier::Meta, _) => "Meta",
    }
}

fn key_glyph(name: &str) -> Option<&'static str> {
    Some(match name.to_ascii_lowercase().as_str() {
        "enter" | "return" => "enter",
        "tab" => "tab",
        "backspace" => "backspace",
        "delete" | "del" => "delete",
        "space" => "space",
        "up" => "arrow-up",
        "down" => "arrow-down",
        "left" => "arrow-left",
        "right" => "arrow-right",
        _ => return None,
    })
}

fn key_text(name: &str) -> String {
    match name.to_ascii_lowercase().as_str() {
        "esc" | "escape" => "Esc".to_string(),
        "pageup" => "PgUp".to_string(),
        "pagedown" => "PgDn".to_string(),
        "capslock" => "Caps".to_string(),
        _ => {
            if name.chars().count() == 1 {
                name.to_uppercase()
            } else {
                name.to_string()
            }
        }
    }
}

/// Mirror `eventCaps`: on macOS all modifiers glyph; elsewhere only meta does
/// in `symbols` mode — `text` mode names every modifier.
fn event_caps(event: &KeystrokeEvent, platform: &str, modifier_style: &str) -> Vec<Cap> {
    let mut caps = Vec::with_capacity(event.modifiers.len() + 1);
    for &modifier in &ordered_modifiers(event.modifiers.clone()) {
        let use_glyph = modifier_style == "symbols"
            && (platform == "macos" || modifier == KeystrokeModifier::Meta);
        caps.push(if use_glyph {
            Cap {
                glyph_id: Some(modifier_glyph(modifier, platform).to_string()),
                text: None,
                is_modifier: true,
            }
        } else {
            Cap {
                glyph_id: None,
                text: Some(modifier_text(modifier, platform).to_string()),
                is_modifier: true,
            }
        });
    }
    if let Some(glyph_id) = key_glyph(&event.key) {
        caps.push(Cap {
            glyph_id: Some(glyph_id.to_string()),
            text: None,
            is_modifier: false,
        });
    } else {
        caps.push(Cap {
            glyph_id: None,
            text: Some(key_text(&event.key)),
            is_modifier: false,
        });
    }
    caps
}

fn caps_key(caps: &[Cap]) -> String {
    caps.iter()
        .map(|cap| {
            cap.glyph_id
                .clone()
                .unwrap_or_else(|| format!("t:{}", cap.text.as_deref().unwrap_or("")))
        })
        .collect::<Vec<_>>()
        .join("|")
}

// ---------------------------------------------------------------------------
// Merge + windows (mirror mergeKeystrokeRows / keystrokeRowWindows)
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct MergedRow {
    caps: Vec<Cap>,
    start_ms: u64,
    last_press_ms: u64,
    repeat: u32,
}

fn merge_rows(events: &[KeystrokeEvent], platform: &str, modifier_style: &str) -> Vec<MergedRow> {
    let mut rows: Vec<MergedRow> = Vec::new();
    for event in events {
        let caps = event_caps(event, platform, modifier_style);
        if let Some(last) = rows.last_mut() {
            if caps_key(&last.caps) == caps_key(&caps)
                && event.t_ms.saturating_sub(last.last_press_ms) <= REPEAT_MERGE_MS
            {
                last.repeat += 1;
                last.last_press_ms = event.t_ms;
                continue;
            }
        }
        rows.push(MergedRow {
            caps,
            start_ms: event.t_ms,
            last_press_ms: event.t_ms,
            repeat: 1,
        });
    }
    rows
}

#[derive(Debug, Clone, Copy)]
struct RowWindow {
    end_ms: f64,
    exit_ms: f64,
}

fn row_windows(rows: &[MergedRow], max_stack: usize, hold_ms: u64) -> Vec<RowWindow> {
    rows.iter()
        .enumerate()
        .map(|(i, row)| {
            let natural_end = (row.last_press_ms + hold_ms) as f64;
            let evict_at = rows
                .get(i + max_stack)
                .map(|row| row.start_ms as f64)
                .unwrap_or(f64::INFINITY);
            if evict_at <= natural_end {
                RowWindow {
                    end_ms: evict_at + EVICT_MS,
                    exit_ms: EVICT_MS,
                }
            } else {
                RowWindow {
                    end_ms: natural_end,
                    exit_ms: EXIT_MS,
                }
            }
        })
        .collect()
}

/// Map source-time windows into output time through the render segments — the
/// keys plane's `enable` expression uses these.
pub(crate) fn keystroke_output_windows(
    segments: &[RenderSegment],
    windows_ms: &[(u64, u64)],
) -> Vec<(u64, u64)> {
    let mut out = Vec::new();
    for segment in segments {
        let out_dur = segment
            .output_end_ms
            .saturating_sub(segment.output_start_ms) as f64;
        let src_dur = segment.source_out_ms.saturating_sub(segment.source_in_ms) as f64;
        if out_dur <= 0.0 || src_dur <= 0.0 {
            continue;
        }
        for &(start, end) in windows_ms {
            let lo = start.max(segment.source_in_ms);
            let hi = end.min(segment.source_out_ms);
            if hi <= lo {
                continue;
            }
            let out_start = segment.output_start_ms as f64
                + (lo - segment.source_in_ms) as f64 * out_dur / src_dur;
            let out_end = segment.output_start_ms as f64
                + (hi - segment.source_in_ms) as f64 * out_dur / src_dur;
            out.push((out_start as u64, out_end.ceil() as u64));
        }
    }
    out.sort_unstable();
    out
}

// ---------------------------------------------------------------------------
// Row SVG (mirror keystroke-row-svg.ts — must be byte-identical)
// ---------------------------------------------------------------------------

/// JS `Math.round` semantics at 2 decimals: ints print bare, decimals `{:.2}`.
fn f(value: f64) -> String {
    let rounded = (value * 100.0 + 0.5).floor() / 100.0;
    if rounded.fract() == 0.0 {
        format!("{}", rounded as i64)
    } else {
        format!("{:.2}", rounded)
    }
}

fn escape_text(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn cap_width(cap: &Cap, m: &Metrics) -> f64 {
    if cap.glyph_id.is_some() {
        m.cap_height
    } else {
        let len = cap
            .text
            .as_deref()
            .map(str::chars)
            .map(|c| c.count())
            .unwrap_or(0)
            .max(1) as f64;
        m.cap_pad_x * 2.0 + len * m.char_advance
    }
}

/// Returns `(svg, width_px, height_px)` — viewBox includes the shadow bleed.
fn keystroke_row_svg(caps: &[Cap], repeat: u32, m: &Metrics, t: &Theme) -> (String, f64, f64) {
    let caps_width: f64 = caps.iter().map(|cap| cap_width(cap, m)).sum();
    let count_label = (repeat > 1).then(|| format!("×{repeat}"));
    let count_width = count_label
        .as_ref()
        .map(|label| m.cap_gap + label.chars().count() as f64 * m.char_advance)
        .unwrap_or(0.0);
    let pill_w =
        m.pill_pad_x * 2.0 + caps_width + m.cap_gap * (caps.len() as f64 - 1.0) + count_width;
    let pill_h = m.pill_pad_y * 2.0 + m.cap_height;

    let pad = m.shadow_blur * 2.0;
    let w = pill_w + pad * 2.0;
    let h = pill_h + pad * 2.0;
    let pill_x = pad;
    let pill_y = pad;
    let caps_y = pill_y + m.pill_pad_y;
    let cap_center_y = caps_y + m.cap_height / 2.0;
    let text_baseline_y = cap_center_y + m.font_px * 0.35;

    let mut s = String::with_capacity(4096);
    use std::fmt::Write;
    let _ = write!(
        s,
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" viewBox=\"0 0 {} {}\">",
        f(w),
        f(h),
        f(w),
        f(h)
    );
    let _ = write!(
        s,
        "<defs><linearGradient id=\"cg\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\
<stop offset=\"0\" stop-color=\"{}\" stop-opacity=\"{}\"/>\
<stop offset=\"1\" stop-color=\"{}\" stop-opacity=\"{}\"/>\
</linearGradient>\
<filter id=\"ds\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\
<feGaussianBlur stdDeviation=\"{}\"/>\
</filter></defs>",
        t.cap_fill_top,
        f(t.cap_fill_top_opacity),
        t.cap_fill_bottom,
        f(t.cap_fill_bottom_opacity),
        f(m.shadow_blur),
    );
    let _ = write!(
        s,
        "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" fill=\"{}\" opacity=\"{}\" filter=\"url(#ds)\"/>",
        f(pill_x),
        f(pill_y + m.shadow_offset_y),
        f(pill_w),
        f(pill_h),
        f(m.pill_radius),
        t.shadow_color,
        f(t.shadow_opacity),
    );
    let _ = write!(
        s,
        "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" fill=\"{}\" fill-opacity=\"{}\" stroke=\"{}\" stroke-opacity=\"{}\"/>",
        f(pill_x),
        f(pill_y),
        f(pill_w),
        f(pill_h),
        f(m.pill_radius),
        t.pill_fill,
        f(t.pill_opacity),
        t.pill_stroke,
        f(t.pill_stroke_opacity),
    );

    let table = glyph_table();
    let mut cap_x = pill_x + m.pill_pad_x;
    for cap in caps {
        let w = cap_width(cap, m);
        let _ = write!(
            s,
            "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" fill=\"url(#cg)\" stroke=\"{}\" stroke-opacity=\"{}\"/>",
            f(cap_x),
            f(caps_y),
            f(w),
            f(m.cap_height),
            f(m.cap_radius),
            t.cap_stroke,
            f(t.cap_stroke_opacity),
        );
        let _ = write!(
            s,
            "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" fill=\"{}\" opacity=\"{}\"/>",
            f(cap_x + 1.0),
            f(caps_y + 1.0),
            f(w - 2.0),
            f((m.cap_height * 0.18).max(1.0)),
            f((m.cap_radius * 0.5).max(1.0)),
            t.cap_highlight,
            f(t.cap_highlight_opacity),
        );
        if let Some(glyph_id) = &cap.glyph_id {
            if let Some(glyph) = table.glyphs.get(glyph_id.as_str()) {
                let scale = m.glyph_box / 24.0;
                let gx = cap_x + (w - m.glyph_box) / 2.0;
                let gy = cap_center_y - m.glyph_box / 2.0;
                let paint = if glyph.fill == "fill" {
                    format!(
                        "fill=\"{}\" opacity=\"{}\" stroke=\"none\"",
                        t.text,
                        f(t.text_opacity)
                    )
                } else {
                    format!(
                        "fill=\"none\" stroke=\"{}\" stroke-opacity=\"{}\" stroke-width=\"{}\" stroke-linecap=\"{}\" stroke-linejoin=\"{}\"",
                        t.text,
                        f(t.text_opacity),
                        f(table.stroke_width),
                        table.stroke_linecap,
                        table.stroke_linejoin,
                    )
                };
                for d in &glyph.paths {
                    let _ = write!(
                        s,
                        "<path d=\"{}\" transform=\"translate({} {}) scale({})\" {}/>",
                        d,
                        f(gx),
                        f(gy),
                        f(scale),
                        paint,
                    );
                }
            }
        } else if let Some(text) = &cap.text {
            let _ = write!(
                s,
                "<text x=\"{}\" y=\"{}\" font-family=\"JetBrains Mono, monospace\" font-size=\"{}\" font-weight=\"600\" fill=\"{}\" fill-opacity=\"{}\" text-anchor=\"middle\">{}</text>",
                f(cap_x + w / 2.0),
                f(text_baseline_y),
                f(m.font_px),
                t.text,
                f(t.text_opacity),
                escape_text(text),
            );
        }
        cap_x += w + m.cap_gap;
    }

    if let Some(label) = &count_label {
        let _ = write!(
            s,
            "<text x=\"{}\" y=\"{}\" font-family=\"JetBrains Mono, monospace\" font-size=\"{}\" font-weight=\"600\" fill=\"{}\" fill-opacity=\"{}\">{}</text>",
            f(cap_x),
            f(text_baseline_y),
            f(m.font_px * 0.85),
            t.count_text,
            f(t.count_text_opacity),
            escape_text(label),
        );
    }

    s.push_str("</svg>");
    (s, w, h)
}

// ---------------------------------------------------------------------------
// Display evaluation (mirror resolveKeystrokeDisplay)
// ---------------------------------------------------------------------------

/// One evaluated row at a source-time instant — produced only for the fixture
/// parity test (the renderer evaluates positions inline).
#[cfg(test)]
#[derive(Debug)]
pub(crate) struct DisplayRow {
    pub svg: String,
    pub width_px: f64,
    pub height_px: f64,
    pub x: f64,
    pub y: f64,
    pub alpha: f64,
    pub scale: f64,
    pub key: String,
}

fn ease_out_cubic(t: f64) -> f64 {
    let u = 1.0 - t.clamp(0.0, 1.0);
    1.0 - u * u * u
}

/// Evaluate the badge stack at a source-time instant. Returns rows ordered
/// newest→oldest (row 0 sits at the anchored edge).
#[cfg(test)]
fn resolve_keystroke_display(
    merged: &[MergedRow],
    windows: &[RowWindow],
    settings: &KeystrokeOverlay,
    metrics: &Metrics,
    theme: &Theme,
    source_ms: f64,
    canvas: (u32, u32),
) -> Vec<DisplayRow> {
    let is_top = settings.position.starts_with("top");
    let anchor_y = if is_top {
        metrics.margin
    } else {
        canvas.1 as f64 - metrics.margin
    };
    let nudge = metrics.cap_height * 0.18 * if is_top { -1.0 } else { 1.0 };

    let mut rows = Vec::with_capacity(settings.max_stack as usize + 1);
    let mut stack_offset = 0.0;
    let step = metrics.cap_height + metrics.pill_pad_y * 2.0 + metrics.row_gap;
    for (i, window) in windows.iter().enumerate().rev() {
        let row = &merged[i];
        if source_ms < row.start_ms as f64 || source_ms >= window.end_ms {
            continue;
        }
        let enter_p = ease_out_cubic((source_ms - row.start_ms as f64) / ENTER_MS);
        let exit_p = ((window.end_ms - source_ms) / window.exit_ms).clamp(0.0, 1.0);
        let alpha = enter_p.min(exit_p);
        if alpha <= 0.0 {
            continue;
        }

        let (svg, svg_w, svg_h) = keystroke_row_svg(&row.caps, row.repeat, metrics, theme);
        let pad = metrics.shadow_blur * 2.0;
        let pill_w = svg_w - pad * 2.0;
        let pill_h = svg_h - pad * 2.0;

        let x = match settings.position.as_str() {
            "bottom-left" | "top-left" => metrics.margin - pad,
            "bottom-right" | "top-right" => canvas.0 as f64 - metrics.margin - pill_w - pad,
            _ => (canvas.0 as f64 - pill_w) / 2.0 - pad,
        };
        let y = if is_top {
            anchor_y + stack_offset - pad + (1.0 - enter_p) * nudge
        } else {
            anchor_y - pill_h - stack_offset - pad + (1.0 - enter_p) * nudge
        };

        rows.push(DisplayRow {
            svg,
            width_px: svg_w,
            height_px: svg_h,
            x,
            y,
            alpha,
            scale: 0.85 + 0.15 * enter_p,
            key: format!("{}", row.start_ms),
        });
        // A row's stack contribution glides with its enter/exit progress.
        stack_offset += step * enter_p * exit_p;
    }
    rows
}

// ---------------------------------------------------------------------------
// Renderer — row SVGs are rasterized once at construction, then blitted
// per frame with the evaluated alpha/scale/position.
// ---------------------------------------------------------------------------

#[derive(Clone)]
struct PreparedRow {
    /// Row artwork document — shared verbatim with the DOM preview; rasterized
    /// lazily into `pixmap_cache` on first draw.
    svg: String,
    svg_w: f64,
    svg_h: f64,
    start_ms: u64,
    end_ms: f64,
    exit_ms: f64,
}

/// Rasterize the badge stack for the export plate feed. `render_frame_at` is
/// a pure function of the output presentation timestamp — window-safe for
/// chunked exports and identical to the editor preview's evaluation.
/// Row pixmaps are rasterized on demand: a long recording can carry hundreds
/// of events, so upfront rasterization would waste memory for rows the export
/// range never shows.
#[derive(Clone)]
pub struct KeystrokeRenderer {
    rows: Vec<PreparedRow>,
    pixmap_cache: std::cell::RefCell<Vec<Option<std::sync::Arc<Pixmap>>>>,
    settings: KeystrokeOverlay,
    metrics: Metrics,
    segments: Vec<RenderSegment>,
    canvas: (u32, u32),
}

impl KeystrokeRenderer {
    /// Prebuild merged rows + display windows (artwork rasterizes lazily).
    pub fn new(
        settings: &KeystrokeOverlay,
        platform: &str,
        events: &[KeystrokeEvent],
        segments: Vec<RenderSegment>,
        canvas: (u32, u32),
    ) -> std::result::Result<Self, String> {
        let metrics = keystroke_metrics(canvas.1 as f64, settings.scale);
        let theme = theme(&settings.theme);
        let merged = merge_rows(events, platform, &settings.modifier_style);
        let windows = row_windows(&merged, settings.max_stack as usize, settings.hold_ms);
        let mut rows = Vec::with_capacity(merged.len());
        for (row, window) in merged.iter().zip(windows.iter()) {
            let (svg, svg_w, svg_h) = keystroke_row_svg(&row.caps, row.repeat, &metrics, &theme);
            rows.push(PreparedRow {
                svg,
                svg_w,
                svg_h,
                start_ms: row.start_ms,
                end_ms: window.end_ms,
                exit_ms: window.exit_ms,
            });
        }
        let cache = std::cell::RefCell::new(vec![None; rows.len()]);
        Ok(Self {
            rows,
            pixmap_cache: cache,
            settings: settings.clone(),
            metrics,
            segments,
            canvas,
        })
    }

    fn row_pixmap(&self, index: usize) -> Option<std::sync::Arc<Pixmap>> {
        let mut cache = self.pixmap_cache.borrow_mut();
        if cache[index].is_none() {
            let row = &self.rows[index];
            let mut pixmap = Pixmap::new(row.svg_w.ceil() as u32, row.svg_h.ceil() as u32)?;
            let options = resvg::usvg::Options {
                fontdb: keystroke_fontdb(),
                ..Default::default()
            };
            let tree = resvg::usvg::Tree::from_str(&row.svg, &options).ok()?;
            resvg::render(&tree, Transform::identity(), &mut pixmap.as_mut());
            cache[index] = Some(std::sync::Arc::new(pixmap));
        }
        cache[index].clone()
    }

    /// Row activity windows mapped into output time — for the FFmpeg `enable`
    /// gate on the keys plane composite.
    pub fn output_windows(&self) -> Vec<(u64, u64)> {
        let source_windows: Vec<(u64, u64)> = self
            .rows
            .iter()
            .map(|row| (row.start_ms, row.end_ms as u64))
            .collect();
        keystroke_output_windows(&self.segments, &source_windows)
    }

    /// Per-row placement for one output timestamp — `(row index, x, y, alpha,
    /// scale)` in canvas space. Shared by the renderer (which rasterizes the
    /// row pixmap on top) and the plane-bounds sweep (which only unions).
    fn layout_rows(&self, output_ms: f64) -> Vec<(usize, f64, f64, f64, f64)> {
        let mut rows = Vec::new();
        if self.rows.is_empty() || !self.settings.enabled {
            return rows;
        }
        let Some(source_ms) = source_time_for_output(&self.segments, output_ms) else {
            return rows;
        };
        let is_top = self.settings.position.starts_with("top");
        let anchor_y = if is_top {
            self.metrics.margin
        } else {
            self.canvas.1 as f64 - self.metrics.margin
        };
        let nudge = self.metrics.cap_height * 0.18 * if is_top { -1.0 } else { 1.0 };

        let mut stack_offset = 0.0;
        let step = self.metrics.cap_height + self.metrics.pill_pad_y * 2.0 + self.metrics.row_gap;
        for (index, row) in self.rows.iter().enumerate().rev() {
            if source_ms < row.start_ms as f64 || source_ms >= row.end_ms {
                continue;
            }
            let enter_p = ease_out_cubic((source_ms - row.start_ms as f64) / ENTER_MS);
            let exit_p = ((row.end_ms - source_ms) / row.exit_ms).clamp(0.0, 1.0);
            let alpha = enter_p.min(exit_p);
            if alpha <= 0.0 {
                continue;
            }
            let scale = 0.85 + 0.15 * enter_p;

            let pad = self.metrics.shadow_blur * 2.0;
            let pill_w = row.svg_w - pad * 2.0;
            let pill_h = row.svg_h - pad * 2.0;

            let x = match self.settings.position.as_str() {
                "bottom-left" | "top-left" => self.metrics.margin - pad,
                "bottom-right" | "top-right" => {
                    self.canvas.0 as f64 - self.metrics.margin - pill_w - pad
                }
                _ => (self.canvas.0 as f64 - pill_w) / 2.0 - pad,
            };
            let y = if is_top {
                anchor_y + stack_offset - pad + (1.0 - enter_p) * nudge
            } else {
                anchor_y - pill_h - stack_offset - pad + (1.0 - enter_p) * nudge
            };
            rows.push((index, x, y, alpha, scale));
            stack_offset += step * enter_p * exit_p;
        }
        rows
    }

    /// Union of the badge rects drawn across `[start_ms, end_ms)` sampled at
    /// `step_ms` — sizes the cropped keys plate for chunked export passes.
    /// Scale happens around each row's center, so the drawn extent is the
    /// row svg rect scaled by `scale`.
    pub fn bounds_in_range(
        &self,
        start_ms: f64,
        end_ms: f64,
        step_ms: f64,
    ) -> Option<(u32, u32, u32, u32)> {
        let mut x0 = f64::MAX;
        let mut y0 = f64::MAX;
        let mut x1 = f64::MIN;
        let mut y1 = f64::MIN;
        let mut time = start_ms;
        while time < end_ms {
            for (index, x, y, _alpha, scale) in self.layout_rows(time) {
                let row = &self.rows[index];
                let cx = x + row.svg_w / 2.0;
                let cy = y + row.svg_h / 2.0;
                x0 = x0.min(cx - row.svg_w * scale / 2.0);
                y0 = y0.min(cy - row.svg_h * scale / 2.0);
                x1 = x1.max(cx + row.svg_w * scale / 2.0);
                y1 = y1.max(cy + row.svg_h * scale / 2.0);
            }
            time += step_ms;
        }
        if x0 > x1 || y0 > y1 {
            return None;
        }
        // ±1px for the AA fringe, clamped to the canvas.
        let rx0 = (x0 - 1.0).floor().max(0.0).min(self.canvas.0 as f64 - 1.0);
        let ry0 = (y0 - 1.0).floor().max(0.0).min(self.canvas.1 as f64 - 1.0);
        let rx1 = (x1 + 1.0).ceil().min(self.canvas.0 as f64).max(rx0 + 1.0);
        let ry1 = (y1 + 1.0).ceil().min(self.canvas.1 as f64).max(ry0 + 1.0);
        Some((
            rx0 as u32,
            ry0 as u32,
            (rx1 - rx0) as u32,
            (ry1 - ry0) as u32,
        ))
    }

    /// Draw the badge stack at `output_ms` into the canvas-sized pixmap.
    /// Pure function of the frame timestamp — no retained animation state.
    /// The export feed uses the offset variant; this stays for the tests.
    #[allow(dead_code)]
    pub fn render_frame_at(&self, output_ms: f64, frame: &mut Pixmap) {
        self.render_frame_at_offset(output_ms, frame, (0.0, 0.0));
    }

    /// Draw into a pixmap representing the `origin`-anchored crop of the
    /// canvas — the keys plate ships only its bounding rect, so canvas-space
    /// row positions shift by `-origin` before scaling.
    pub fn render_frame_at_offset(&self, output_ms: f64, frame: &mut Pixmap, origin: (f64, f64)) {
        for (index, x, y, alpha, scale) in self.layout_rows(output_ms) {
            let Some(pixmap) = self.row_pixmap(index) else {
                continue;
            };
            let row = &self.rows[index];
            let (row_w, row_h) = (row.svg_w, row.svg_h);
            let x = x - origin.0;
            let y = y - origin.1;

            // Scale around the row's own center, matching the DOM preview's
            // `transform: scale()` on the row box.
            let cx = x + row_w / 2.0;
            let cy = y + row_h / 2.0;
            let transform = Transform::from_translate(cx as f32, cy as f32)
                .pre_scale(scale as f32, scale as f32)
                .pre_translate(-row_w as f32 / 2.0, -row_h as f32 / 2.0);
            let paint = PixmapPaint {
                opacity: alpha as f32,
                ..Default::default()
            };
            frame.draw_pixmap(0, 0, pixmap.as_ref().as_ref(), &paint, transform, None);
        }
    }
}

// ---------------------------------------------------------------------------
// Fixture parity + unit tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;

    #[derive(Debug, Deserialize)]
    struct Fixture {
        cases: Vec<FixtureCase>,
    }
    #[derive(Debug, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct FixtureCase {
        id: String,
        platform: String,
        settings: FixtureSettings,
        canvas: FixtureCanvas,
        events: Vec<FixtureEvent>,
        samples: Vec<FixtureSample>,
    }
    #[derive(Debug, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct FixtureSettings {
        enabled: bool,
        position: String,
        theme: String,
        scale: f64,
        max_stack: u32,
        hold_ms: u64,
        modifier_style: String,
    }
    #[derive(Debug, Deserialize)]
    struct FixtureCanvas {
        width: u32,
        height: u32,
    }
    #[derive(Debug, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct FixtureEvent {
        t_ms: u64,
        key: String,
        modifiers: Vec<KeystrokeModifier>,
    }
    #[derive(Debug, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct FixtureSample {
        source_ms: f64,
        rows: Vec<FixtureRow>,
    }
    #[derive(Debug, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct FixtureRow {
        key: String,
        x: f64,
        y: f64,
        width_px: f64,
        height_px: f64,
        alpha: f64,
        scale: f64,
        svg: String,
    }

    fn settings(f: &FixtureSettings) -> KeystrokeOverlay {
        KeystrokeOverlay {
            enabled: f.enabled,
            position: f.position.clone(),
            theme: f.theme.clone(),
            scale: f.scale,
            max_stack: f.max_stack,
            hold_ms: f.hold_ms,
            modifier_style: f.modifier_style.clone(),
        }
    }

    /// TS ↔ Rust contract: the committed fixture regenerates identically —
    /// same rows, same positions, byte-identical row SVG strings.
    #[test]
    fn keystroke_layout_fixtures_match_typescript() {
        let fixture: Fixture =
            serde_json::from_str(include_str!("../testdata/keystroke-layouts.json"))
                .expect("keystroke-layouts.json must parse");
        assert_eq!(fixture.cases.len(), 3);
        for case in &fixture.cases {
            let settings = settings(&case.settings);
            let metrics = keystroke_metrics(case.canvas.height as f64, case.settings.scale);
            let theme = theme(&case.settings.theme);
            let events: Vec<KeystrokeEvent> = case
                .events
                .iter()
                .map(|e| KeystrokeEvent {
                    t_ms: e.t_ms,
                    key: e.key.clone(),
                    modifiers: e.modifiers.clone(),
                })
                .collect();
            let merged = merge_rows(&events, &case.platform, &case.settings.modifier_style);
            let windows = row_windows(
                &merged,
                case.settings.max_stack as usize,
                case.settings.hold_ms,
            );
            for sample in &case.samples {
                let rows = resolve_keystroke_display(
                    &merged,
                    &windows,
                    &settings,
                    &metrics,
                    &theme,
                    sample.source_ms,
                    (case.canvas.width, case.canvas.height),
                );
                assert_eq!(
                    rows.len(),
                    sample.rows.len(),
                    "case {} @ {}ms row count",
                    case.id,
                    sample.source_ms
                );
                for (row, expected) in rows.iter().zip(sample.rows.iter()) {
                    assert_eq!(row.key, expected.key, "case {} row key", case.id);
                    assert!(
                        (row.x - expected.x).abs() < 0.01
                            && (row.y - expected.y).abs() < 0.01
                            && (row.width_px - expected.width_px).abs() < 0.01
                            && (row.height_px - expected.height_px).abs() < 0.01
                            && (row.alpha - expected.alpha).abs() < 0.01
                            && (row.scale - expected.scale).abs() < 0.01,
                        "case {} row geometry mismatch",
                        case.id
                    );
                    assert_eq!(row.svg, expected.svg, "case {} row svg diverged", case.id);
                }
            }
        }
    }

    fn ev(t: u64, key: &str, mods: &[KeystrokeModifier]) -> KeystrokeEvent {
        KeystrokeEvent {
            t_ms: t,
            key: key.into(),
            modifiers: mods.to_vec(),
        }
    }

    fn seg(src_in: u64, src_out: u64, out_start: u64, out_end: u64) -> RenderSegment {
        RenderSegment {
            asset_id: "a".into(),
            stream_index: None,
            volume: None,
            fade_in_ms: None,
            fade_out_ms: None,
            volume_keyframes: None,
            audio_filter: None,
            speed: 1.0,
            source_in_ms: src_in,
            source_out_ms: src_out,
            output_start_ms: out_start,
            output_end_ms: out_end,
            source_width: None,
            source_height: None,
        }
    }

    #[test]
    fn merge_rows_collapses_quick_repeats() {
        let events = vec![
            ev(1000, "Z", &[KeystrokeModifier::Ctrl]),
            ev(1400, "Z", &[KeystrokeModifier::Ctrl]),
            ev(5000, "Z", &[KeystrokeModifier::Ctrl]),
        ];
        let rows = merge_rows(&events, "windows", "symbols");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].repeat, 3 - 1);
        assert_eq!(rows[1].repeat, 1);
    }

    #[test]
    fn output_windows_map_through_segments() {
        // 2x speed: source 1000..3000 plays in output 0..1000.
        let segments = vec![seg(1000, 3000, 0, 1000)];
        let windows = keystroke_output_windows(&segments, &[(1100, 2100)]);
        assert_eq!(windows, vec![(50, 550)]);
    }

    #[test]
    fn renderer_draws_badge_inside_window() {
        let settings = KeystrokeOverlay {
            enabled: true,
            position: "bottom-center".into(),
            theme: "dark".into(),
            scale: 1.0,
            max_stack: 3,
            hold_ms: 2000,
            modifier_style: "symbols".into(),
        };
        let segments = vec![seg(0, 10_000, 0, 10_000)];
        let events = vec![ev(1000, "S", &[KeystrokeModifier::Ctrl])];
        let renderer =
            KeystrokeRenderer::new(&settings, "windows", &events, segments, (640, 360)).unwrap();
        let mut frame = Pixmap::new(640, 360).unwrap();

        renderer.render_frame_at(500.0, &mut frame);
        assert!(
            frame.data().iter().all(|px| *px == 0),
            "no badge before event"
        );

        renderer.render_frame_at(1500.0, &mut frame);
        let lit = frame
            .data()
            .as_chunks::<4>()
            .0
            .iter()
            .filter(|px| px[3] > 0)
            .count();
        assert!(lit > 500, "badge pixels drawn inside window: {lit}");

        frame.fill(tiny_skia::Color::TRANSPARENT);
        renderer.render_frame_at(5000.0, &mut frame);
        assert!(
            frame.data().iter().all(|px| *px == 0),
            "badge gone after hold window"
        );
    }
}
